package com.bank.statement;

import java.util.*;
import java.util.logging.*;
import java.util.stream.IntStream;

public class OrderedDemo {
    private static final Logger log = Logger.getLogger("Statement");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> txns = IntStream.rangeClosed(1, 8).boxed().toList();
        StatementPrinter printer = new StatementPrinter();

        log.info("unordered (parallel forEach) — order NOT guaranteed:");
        printer.printUnordered(txns);
        log.info("ordered (parallel forEachOrdered) — encounter order preserved:");
        printer.printOrdered(txns);
    }
}

// ─── Would be in service/StatementPrinter.java ───
class StatementPrinter {
    void printUnordered(List<Integer> txns) {
        txns.parallelStream().forEach(t -> System.out.print(t + " ")); // jumbled
        System.out.println();
    }
    void printOrdered(List<Integer> txns) {
        txns.parallelStream().forEachOrdered(t -> System.out.print(t + " ")); // 1..8 in order
        System.out.println();
    }
}
